public class Factorial {
    public static int fact(int n) {
        if (n <= 1) {
            return 1;
        }
        return n * fact(n - 1);
    }

    public static void main(String[] args) {
        int num = 4;
        int result = fact(num);
        System.out.println("Factorial of " + num + " is " + result);
    }
}

